# Texto da aba "Métodos e fontes", em markdown, usado pela página em Quarto e pelo app Shiny.
#
# Uma só fonte para os dois: a diferença está em quatro frases que dependem de como os modelos são ajustados.
#   - Quarto (resumo != NULL): todos os recortes foram ajustados antes, então o texto cita contagens e valores do recorte "Todos os locais, todas as idades".
#   - Shiny (resumo = NULL): os modelos são ajustados quando o recorte é escolhido; o texto explica isso e remete à nota abaixo da figura.

fmt <- function(x, d = 0) formatC(x, format = "f", digits = d, big.mark = ".", decimal.mark = ",")
fd <- function(x) format(as.Date(x), "%d/%m/%Y")
mm <- function(ym) paste0(substr(ym, 6, 7), "/", substr(ym, 1, 4))
rr_txt <- function(v) sprintf("%s (IC 95%%: %s a %s)", fmt(v[1], 2), fmt(v[2], 2), fmt(v[3], 2))

# Tabela de reconciliação das causas: óbitos por grupo de causa básica (soma = total de óbitos elegíveis, os da população nos dias da série),
# a que opção do seletor Causa do óbito cada grupo pertence e o detalhe dos códigos que explicam a classificação. r = M$reconc (reconciliar_causas).
tabela_reconciliacao <- function(r) {
  if (is.null(r) || is.null(r$grupos)) return("")
  rot <- c(naturais = "Naturais", todas_sem_covid = "Todas, exceto COVID-19", todas = "Todas, com COVID-19", externas = "Externas")
  g <- r$grupos
  em <- vapply(g$grupo, function(gr) paste(rot[names(CAUSA_GRUPOS)[vapply(CAUSA_GRUPOS, function(v) gr %in% v, TRUE)]], collapse = "; "), "")
  linhas <- paste0("| ", g$rotulo, " | ", fmt(g$n), " | ", em, " |\n", collapse = "")
  opc <- paste0(vapply(names(rot), function(k) paste0(rot[[k]], ": ", fmt(r$opcoes[[k]])), ""), collapse = "; ")
  det <- paste0("- ", r$detalhe$rotulo, ": ", fmt(r$detalhe$n), "\n", collapse = "")
  paste0("**Reconciliação das causas.** Dos ", fmt(r$total), " óbitos elegíveis (os da população selecionada nos dias da série), cada um pertence a um só grupo de causa básica:\n\n",
         "| Grupo de causa básica | Óbitos | Opções do seletor |\n|:--|--:|:--|\n", linhas,
         "| **Total de óbitos elegíveis** | **", fmt(r$total), "** | |\n\n",
         "Óbitos por opção do seletor: ", opc, ". Detalhe dos códigos:\n\n", det, "\n")
}

# M: meta da Figura 1 (base_figura1); n_sem_idade: óbitos sem idade informada;
# resumo: resumo_figura1() (só no Quarto); dados: list(sim_atualizado, clima_atualizado, repo_sim, gerado_em) (só no Shiny)
texto_metodos <- function(M, n_sem_idade, resumo = NULL, dados = NULL) {
  demanda <- is.null(resumo)
  pop_txt <- if (M$pop == "res") "residentes no Rio com óbito ocorrido no próprio município" else "todos os óbitos ocorridos no Rio, residentes ou não"
  nc_txt <- if (length(M$meses_nc)) paste(mm(M$meses_nc), collapse = ", ") else "nenhum"
  h <- M$exposicoes$horas$ref; a <- M$exposicoes$haat$ref
  pg <- function(...) paste0(paste0(..., collapse = ""), "\n\n")

  intro <- if (demanda)
    "Esta página apresenta a Figura 1 do painel, desenvolvido em R e Shiny. O servidor obtém os dados diretamente das Releases do GitHub e ajusta o modelo de cada recorte (combinação de filtros) no momento em que ele é selecionado (de 3 a 15 segundos na primeira solicitação). O resultado é armazenado no servidor, de modo que as consultas seguintes ao mesmo recorte, feitas por qualquer usuário, são atendidas de imediato até a próxima atualização dos dados. Cada combinação de local do óbito, faixa etária, raça/cor, causa do óbito e retiradas do ajuste tem um modelo próprio."
  else
    "Esta página apresenta a Figura 1 do painel, reescrita em R e Quarto. O processamento dos dados e o ajuste dos modelos são feitos em R (`calcular_figura1.R`), e os resultados ficam incorporados a este arquivo, que abre diretamente no navegador. Como cada recorte (combinação de local do óbito, faixa etária e raça/cor) já tem o seu modelo calculado, a troca de filtros não reestima os modelos."

  causas_p <- if (demanda)
    pg("O seletor Causa do óbito oferece quatro séries: causas naturais (padrão, definidas acima), todas as causas exceto COVID-19, todas as causas com COVID-19 e causas externas. Neste painel, causas externas são os óbitos com causa básica nos códigos V01 a Y98 da CID-10. Os códigos S00 a T98 descrevem a natureza da lesão e, pelas regras de codificação da CID-10, não deveriam ser a causa básica. Quando aparecem, assim como as causas básicas ausentes e os códigos inválidos, formam grupos próprios, que entram apenas em Todas as causas. A tabela de reconciliação, na seção Dados, mostra quantos óbitos há em cada grupo e a quais opções do seletor ele pertence. Cada causa tem a sua própria série de óbitos, e a lista de recortes com óbitos suficientes varia conforme a causa.")
  else ""
  retirar_p <- if (demanda) paste0(
    "### Retirar períodos do ajuste\n\n",
    pg("O ajuste principal é a amostra descrita em Período e registro do SIM: as caixas Meses com registro não consolidado e Dias sem dados de clima vêm marcadas, e o período da COVID-19 permanece no ajuste, com o termo `s(COVID)` absorvendo o excesso. Três caixas de seleção, no grupo Retirar do ajuste do modelo, alteram essa escolha. Cada caixa marcada exclui os dias correspondentes dos dados usados para estimar o modelo (os dias sem registro no SIM são sempre excluídos):"),
    "- Período da COVID-19 (", fd(M$covid[1]), " a ", fd(M$covid[2]), "), desmarcada por padrão: o modelo é ajustado sem esses dias e deixa de ter o termo `s(COVID)`.\n",
    "- Meses com registro não consolidado (", nc_txt, "), marcada por padrão: os dias desses meses são excluídos do ajuste. Desmarcada, é a sensibilidade em que o modelo usa esses meses, nos quais o número de óbitos observado pode estar abaixo do real.\n",
    "- Dias sem dados de clima e os ", M$lag, " seguintes, marcada por padrão: esses dias são excluídos do ajuste, junto com os ", M$lag, " dias posteriores a cada um, porque a defasagem de 0 a ", M$lag, " dias usa o clima dos dias anteriores. Desmarcada, os dias sem clima contam como dias sem calor, que é a especificação anterior do painel; ela trata a falta de medição como ausência de calor e fica disponível só como sensibilidade.\n\n",
    pg("Semanas com algum dia fora do ajuste ficam sem esperado. Cada combinação de causa e de retiradas corresponde a um modelo distinto, ajustado e armazenado no servidor na primeira solicitação. O mínimo de ", M$min_obitos, " óbitos considera apenas os dias mantidos no ajuste."))
  else ""

  curvas_p <- if (demanda) paste0(
    "### Curvas de exposição-resposta e de defasagem\n\n",
    pg("A aba Exposição-resposta e defasagem mostra, para o recorte escolhido, duas figuras obtidas do mesmo modelo que gera o esperado sem calor. A Figura 2 traz o RR acumulado em 0 a ", M$lag, " dias em função da exposição, mantida constante em todos os dias da janela, em relação a nenhuma exposição. O intervalo de confiança de 95% usa a matriz de covariância dos coeficientes da cross-basis (função `crosspred` do pacote `dlnm`). A grade de exposição vai de zero ao percentil 99 dos dias com exposição, porque acima disso há poucos dias. A Figura 3 é um gráfico de floresta, nos dois níveis de referência: a parte superior traz o RR de cada defasagem de 0 a ", M$lag, " (efeito da exposição ocorrida l dias antes do óbito) e a parte inferior traz o RR acumulado de 0 até l, para l igual a 1, 3, 7 e ", M$lag, ". O RR acumulado até l é o produto dos RR por defasagem de 0 a l, com intervalo de confiança de 95% a partir da matriz de covariância dos coeficientes, e as duas partes usam escalas horizontais diferentes. Os quadros do topo trazem o RR no mesmo dia (lag 0) e os RR acumulados em 0 a 3 e em 0 a ", M$lag, " dias."),
    pg("Com a medida de horas, a resposta à exposição tem 1 grau de liberdade: o logaritmo do RR é uma reta nas horas por construção, a curva não identifica limiar nem curvatura e RR(8 h) = RR(4 h)². Os RR de 4 e de 8 horas do modelo de referência são, portanto, um só achado, lido em dois pontos da mesma reta. Para verificar se os dados sustentam essa forma, a aba refaz o ajuste do mesmo recorte, da mesma causa e com as mesmas retiradas, trocando só a função da exposição por um spline natural com 3 graus de liberdade e nós interiores em 3 e 6 horas, definidos antes da análise e sem otimização (curva flexível pré-definida). A Figura 2 desenha a curva flexível tracejada sobre a reta, com o IC 95% de cada uma, e as barras logo abaixo mostram quantos dias do ajuste têm cada número de horas, para que se veja onde há dados. O Quadro 3 traz, para a reta e para a curva flexível, os graus de liberdade, o RR com 4 e com 8 horas, o RR de 8 horas contra 4 horas, a razão entre o log RR de 8 e o de 4 horas (2 na reta), o AIC e a comparação aproximada dos dois ajustes por razão de desvios (função `anova` do `mgcv`, com a reta contida na curva flexível). Como os resíduos têm autocorrelação, o valor de p dessa comparação é indicativo. O IC da reta é mais estreito que o da curva flexível nas extremidades porque a forma está imposta, e não porque haja mais dados nessa região."),
    pg("O RR acumulado em 0 a ", M$lag, " dias descreve a exposição de referência mantida em todos os ", M$lag + 1, " dias, e a série pode quase não ter essa sequência. O Quadro 4 mostra o suporte de cada contraste. Dia exposto é o dia com exposição de pelo menos o nível de referência (4 e 8 h por dia, ou 5 e 20 °C·h por dia; dia sem dado de clima conta como não exposto). Para as durações de 1, 2, 4, 8 e ", M$lag + 1, " dias, o quadro conta as janelas (dias do óbito no ajuste em que os d dias terminados nele são todos expostos) e os eventos independentes (conjuntos de dias expostos separados de outros por pelo menos ", M$lag, " dias sem exposição, de modo que as janelas de defasagem de eventos diferentes não se tocam), e traz ao lado o RR acumulado do mesmo contraste (defasagens de 0 a d-1, que supõe exposição nos d últimos dias e nenhuma antes). A duração observada das sequências de dias expostos e a distribuição por ano (dias expostos, sequências de 4 dias ou mais e janelas de ", M$lag + 1, " dias) completam o quadro. A coluna Leitura classifica cada linha pelo número de eventos independentes (menos de 5: extrapolação; de 5 a 29: poucos eventos; 30 ou mais: frequente), limiares que são uma convenção do painel e não um critério estatístico. O suporte depende só da exposição e dos dias do ajuste, e por isso é o mesmo em qualquer recorte; só o RR muda com o recorte."),
    pg("O HAAT usa spline penalizado de 15 graus de liberdade na exposição combinado com 3 graus de liberdade na defasagem, o que dá uma base cruzada de 45 colunas (k'). A penalização reduz a flexibilidade efetiva, e o Quadro 3 informa os graus de liberdade efetivos do ajuste ao lado de k'. A curva do HAAT é estimada, e não imposta, mas as extremidades têm poucos dias de exposição alta e intervalos largos. A aba tem filtros próprios de recorte, causa do óbito e retirada do ajuste, e reaproveita os modelos já ajustados nas outras abas."),
    pg("O seletor Comparar com (local do óbito) acrescenta um segundo recorte, que difere do primeiro apenas no local do óbito: os demais filtros valem para os dois. Os recortes aparecem em colunas, cada um com quadros, Figuras 2, 3 e 4 e interpretação próprios, e as Figuras 2 e 3 usam a mesma escala nos dois lados. O texto de comparação traz o RR acumulado dos dois locais e informa se os intervalos de confiança se sobrepõem, o que é uma comparação informal e não um teste da diferença. Quando um dos recortes é Todos os locais, ele inclui os óbitos do outro e as duas estimativas não são independentes."))
  else ""

  mapa_p <- if (demanda) paste0(
    "### Mapa de horas por dia e limiar do índice de calor\n\n",
    pg("A Figura 4 refaz, com o modelo de referência, o mapa de horas por dia e limiar da versão anterior do painel. Para cada limiar K (32 a 44 °C) e cada número mínimo de horas H (1, 2, 3, 4, 6, 8, 10 e 12), a exposição é binária: vale 1 nos dias com pelo menos H horas de índice de calor igual ou superior a K, e 0 nos demais, inclusive nos dias sem dado de clima. Cada célula é um modelo próprio, com o mesmo GAM da Figura 1 (binomial negativa, spline do tempo, ciclo anual e termo do período COVID) e a mesma defasagem de 0 a ", M$lag, " dias, com cross-basis linear na exposição e spline natural de 3 graus de liberdade na defasagem. O RR de cada célula é o acumulado em 0 a ", M$lag, " dias para a exposição mantida em todos os ", M$lag + 1, " dias, em relação a nenhum dia exposto, com intervalo de confiança de 95% a partir da matriz de covariância dos coeficientes."),
    pg("A versão anterior definia a exposição como um dia com a condição em t, t−1, t−2 ou t−3 e estimava cada célula por quase-Poisson com termo de dia da semana. O modelo atual usa a defasagem distribuída do DLNM e não tem termo de dia da semana, de modo que os RR das duas versões não são comparáveis em valor. Células com menos de 15 dias expostos no ajuste, ou com menos de 30 dias sem exposição, não são estimadas. As 104 células são ajustadas de forma independente, são aninhadas por construção (um dia com mais horas também entra nas definições com menos horas) e não passam por correção para comparações múltiplas; o mapa é descritivo. As colunas são calculadas sob demanda, uma por limiar, e ficam guardadas no servidor para os pedidos seguintes."))
  else ""

  cid_p <- if (demanda) paste0(
    "### Causas específicas (CID-10)\n\n",
    pg("A aba Causas específicas (CID-10) estima, para o recorte escolhido, o RR em dias de calor de cada causa básica de óbito com 3 caracteres da CID-10. Cada causa com pelo menos ", fmt(M$cid_min), " óbitos nos dias do ajuste é avaliada em um modelo próprio, com a estrutura do modelo de referência (binomial negativa, spline do tempo, ciclo anual, termo do período da COVID-19 quando restam dias dele no ajuste e cross-basis de defasagem de 0 a ", M$lag, " dias), aplicado à série diária de óbitos daquela causa e com as mesmas retiradas do ajuste do recorte. A medida de calor e o nível de exposição (um dos dois níveis de referência) são escolhidos na aba. O RR é o acumulado em 0 a ", M$lag, " dias para a exposição mantida em todos os ", M$lag + 1, " dias, em relação a nenhuma exposição. O IC 95% usa a matriz de covariância dos coeficientes, e o valor de p vem da aproximação normal do logaritmo do RR."),
    pg("Como a aba avalia dezenas de causas de uma só vez, parte dos RR diferentes de 1 apareceria por acaso. A correção de Benjamini e Hochberg controla a taxa de falsas descobertas dentro da família formada pelas causas do conjunto e do capítulo escolhidos, e o valor q resultante só é calculado quando todas as causas da família estão estimadas. As causas com q < 0,05 ficam destacadas, e uma caixa permite incluir as demais, em cinza. Mudar o conjunto ou o capítulo muda a família e, portanto, o q. O conjunto Causas selecionadas do referencial reúne as causas dos 15 grupos do estudo de referência (Morais et al.), escritos em códigos de 3 caracteres: influenza e pneumonia (J09, J12 a J18); doenças respiratórias crônicas inferiores (J40 a J47); outras doenças respiratórias (J00 a J06, J20 a J39, J60 a J70, J80 a J99, R09 e U04); doenças hipertensivas (I10 a I15); doenças isquêmicas do coração (I20 a I25); insuficiência cardíaca (I50); doenças cerebrovasculares (I60 a I69); outras doenças do aparelho circulatório (I00 a I09, I26 a I49, I51, I52 e I70 a I99); neoplasias malignas (C00 a C97); Alzheimer e demência (G30, G31, F01 e F03); diabetes (E10 a E14); insuficiência renal (N17 a N19); sepse (A40 e A41); infecção do trato urinário (N39); e causas mal definidas (capítulo R). A lista é fixa e não depende dos resultados do painel. O estudo de referência modela esses grupos, e esta aba estima cada causa de 3 caracteres dentro deles."),
    pg("Cada causa é pedida ao servidor separadamente, no máximo duas ao mesmo tempo, e o resultado fica guardado em disco. Por isso a figura se completa causa a causa, e a primeira abertura de um recorte leva de 3 a 10 segundos por causa. Ao clicar em uma causa, a Figura 5b mostra seus óbitos semanais observados e o esperado sem calor do modelo daquela causa, com a faixa de 95% calculada como na Figura 1. Os nomes das causas vêm do arquivo `dados_auxiliares/cid_nomes.json`, que cobre as causas de 3 caracteres avaliadas."))
  else ""

  recon_p <- tabela_reconciliacao(M$reconc)

  dia_p <- if (demanda) paste0(
    "### Diagnósticos e análises de sensibilidade\n\n",
    pg("A aba Diagnósticos e sensibilidades publica, para o recorte escolhido, os diagnósticos do modelo principal e refaz o ajuste com uma mudança por vez. O Quadro 1 traz a autocorrelação (ACF) dos resíduos de Pearson até 35 dias, que ignora os dias fora do ajuste e usa o limite aproximado de ±1,96 ÷ √n; o teste de Ljung-Box com ", 14, " defasagens, sem desconto dos graus de liberdade do modelo, de modo que o valor de p é indicativo; o `k.check` do pacote `mgcv` (índice k e valor de p, com 200 permutações e semente fixa) para cada termo suave; a dimensão da base e os graus de liberdade efetivos de cada termo e da base cruzada; a dispersão residual (χ² de Pearson dividido pelos graus de liberdade residuais, que na binomial negativa fica perto de 1 por construção); e a convergência do REML."),
    pg("O Quadro 2 refaz o ajuste do mesmo recorte, da mesma causa e com as mesmas retiradas, mudando uma escolha por vez: dia da semana como termo do modelo; spline do tempo com metade e com o dobro dos nós; defasagem máxima de 7 e de 14 dias (a janela de retirada dos dias sem clima acompanha a defasagem); quatro alternativas para o período da COVID-19 (retirado do ajuste; mantido sem termo próprio; termo não cíclico com indicador do período; termo pelos óbitos diários de COVID-19 em média móvel de 7 dias); meses não consolidados mantidos; dias sem clima contados como dias sem calor; e a especificação anterior do painel. Cada linha traz os dias e os óbitos no ajuste, os dias de calor (pelo menos 4 h com índice de calor igual ou superior a 36 °C) e os eventos (sequências de dias seguidos de calor), o RR e o IC 95% nos dois níveis de referência e o resumo do diagnóstico residual. A variação do log-RR em relação ao ajuste principal é calculada em cada nível, e variações de 20% ou mais são marcadas. A interpretação compara os valores estimados e não depende de o intervalo de confiança cruzar o 1."),
    pg("O termo `s(COVID)` do modelo de referência usa um spline cíclico sobre o índice de dias do período, com valor 0 fora dele. A natureza cíclica obriga o valor do último dia do período a coincidir com o do índice 0, e a aba mostra o valor do termo fora do período, no primeiro dia, no último e no pico. As alternativas listadas acima indicam quanto o RR depende dessa escolha."))
  else ""

  pop_frase <- if (demanda) "A população selecionada corresponde a" else "A população desta versão corresponde a"

  trocas <- if (demanda)
    "A família binomial negativa é a padrão. Em séries muito esparsas, nas quais ela não converge, o ajuste usa a família quase-Poisson, e a nota abaixo da figura informa a família utilizada em cada recorte."
  else
    paste0("Séries muito esparsas, nas quais a binomial negativa não converge, usam a família quase-Poisson. ",
           if (sum(unlist(resumo$n_qp)) == 0) "Nesta execução, nenhum dos " else paste0("Nesta execução, ", sum(unlist(resumo$n_qp)), " dos "),
           fmt(2 * resumo$n_segmentos), if (sum(unlist(resumo$n_qp)) <= 1) " ajustes precisou dessa troca." else " ajustes precisaram dessa troca.")

  rr_frase <- paste0("O risco relativo (RR) acumulado apresentado nos indicadores corresponde à exposição ao nível de referência de calor em todos os ", M$lag + 1, " dias (o dia e os 10 anteriores), em relação à ausência de calor.",
                     if (!demanda) paste0(" Para todos os locais e idades, o RR com ", h[1], " h por dia é ", rr_txt(resumo$rr_total$horas[1:3]),
                                          " e com ", h[2], " h por dia é ", rr_txt(resumo$rr_total$horas[4:6]), "."))

  phi_frase <- if (demanda) "O valor de φ de cada recorte aparece na nota abaixo da figura."
               else paste0("Para todos os locais e idades, φ é ", fmt(resumo$phi_total$horas, 2), ".")

  repro <- if (demanda)
    paste0("```\nRscript shiny/atualizar_cache.R\n```\n\nO aplicativo Shiny e a página em Quarto utilizam as mesmas funções de R (pasta `R/`); assim, o mesmo recorte produz o mesmo resultado nos dois. ",
           "Pacotes de R: `shiny`, `mgcv`, `dlnm`, `nanoparquet`, `jsonlite`, `future` e `promises`.")
  else
    paste0("```\nRscript calcular_figura1.R --silver entrada/sim/silver --haat entrada/haat_diario_municipal.csv\nquarto render painel_figura1.qmd\n```\n\n",
           "Pacotes de R: `mgcv`, `dlnm`, `nanoparquet`, `jsonlite`, `knitr`.")
  versao <- if (demanda)
    paste0(" Fonte e data da extração: SIM atualizado em ", dados$sim_atualizado, " (", dados$repo_sim, ") e clima atualizado em ", dados$clima_atualizado, " (horários em UTC); cache gerado em ", dados$gerado_em, ".")
  else paste0(" Versão dos dados desta página: gerada em ", M$gerado_em, ".")

  paste0(
    "## Métodos e fontes\n\n",
    pg(intro),
    "### Dados\n\n",
    pg("Os óbitos provêm do Sistema de Informações sobre Mortalidade (SIM/DATASUS), por meio do repositório de dados (data lake) do projeto, em sua camada silver, com os óbitos ocorridos no município do Rio de Janeiro desde 2006. ",
        pop_frase, " ", pop_txt, ": ", fmt(M$n_obitos), " óbitos por causas naturais entre ", fd(M$inicio), " e ", fd(M$fim),
        ". Causa natural é aquela registrada nos capítulos I a XVIII da CID-10 (códigos A00 a R99), exceto a COVID-19. A COVID-19 é identificada pelo código completo da causa básica: B34.2 (infecção por coronavírus de localização não especificada, usada no início de 2020) e U07 (U07.1 e U07.2). Os demais códigos B34 (B34.0, B34.1 e B34.3 a B34.9), que são outras infecções virais, permanecem nas causas naturais", if (demanda) "." else ". Os óbitos por COVID-19 ficam fora de todas as séries."),
    causas_p,
    recon_p,
    pg("O local do óbito parte do campo LOCOCOR do SIM e é refinado pelo tipo de estabelecimento registrado no Cadastro Nacional de Estabelecimentos de Saúde (CNES): os tipos 5, 7, 15 e 62 correspondem a Hospital; os tipos 20, 21 e 73, a UPA / pronto atendimento (UPA: Unidade de Pronto Atendimento); e os demais estabelecimentos de saúde, a Outros estabelecimentos. Domicílio, via pública, outros locais e ignorado são os registrados diretamente no LOCOCOR."),
    pg("As faixas etárias, definidas para este estudo, são 0-4, 5-9, 10-19, 20-29, 30-39, 40-49, 50-59, 60-69, 70-79 e 80 anos ou mais. Os ", fmt(n_sem_idade), " óbitos sem idade informada entram apenas em Todas as idades."),
    pg("A raça/cor provém do campo RACACOR. Branca, preta e parda têm série própria, e o agregado PPI reúne preta, parda e indígena. As categorias indígena e amarela não têm óbitos suficientes para série própria, e os óbitos com raça/cor ignorada ou não informada entram apenas em Todas. As séries por raça/cor são calculadas para todas as idades."),
    pg("O clima é a série diária municipal `haat_diario_municipal.csv`, calculada a partir do repositório de dados climáticos do projeto (Instituto Nacional de Meteorologia, INMET, e Alerta Rio): média horária das estações, índice de calor pela equação do National Weather Service dos Estados Unidos (Rothfusz, 1990) e horas acima de cada limiar (HAAT). A metodologia segue Morais et al. (repositório *heat_mortality_MRJ_article*, usado com autorização). Há dados de clima a partir de 17/04/2007. Dia sem dado de clima (", fmt(M$dias_sem_clima), " dias na série) é dado ausente, e não dia sem calor: no ajuste principal esses dias e os ", M$lag, " seguintes ficam fora do modelo, e os óbitos deles continuam nos gráficos."),
    "### Período e registro do SIM\n\n",
    pg("A série termina na menor das duas datas: o último dia com óbito registrado no SIM e o último dia com dados de clima. Os dias sem nenhum óbito registrado (", fmt(M$dias_sem_registro),
        " dias) correspondem a arquivo ainda não carregado: são excluídos do ajuste e aparecem em cinza claro."),
    pg("Um mês é classificado como de registro não consolidado quando atende a pelo menos uma de três regras, todas baseadas na completude do registro e nenhuma no valor do RR: (1) a taxa diária de óbitos é inferior a 80% da mediana dos 12 meses de referência anteriores; (2) há pelo menos um dia sem nenhum óbito entre o primeiro e o último dia do arquivo; (3) é o último mês do arquivo e este termina antes do último dia do mês. A taxa do mês é o número de óbitos dividido pelo número de dias com algum óbito registrado; os meses do período da COVID-19 e os já classificados como não consolidados não compõem a referência. Nesta versão, os meses não consolidados são ", nc_txt, " (", fmt(M$dias_nc), " dias)", if (demanda) ". Eles aparecem hachurados nos gráficos" else ", hachurados nos gráficos", "."),
    pg("A amostra principal do ajuste retira, além dos dias sem registro no SIM, os meses não consolidados e os dias sem dado de clima com os ", M$lag, " seguintes. O período da COVID-19 permanece no ajuste, com o termo `s(COVID)`. Os óbitos dos dias retirados continuam nos gráficos e são contados à parte, por motivo, na nota abaixo da figura.", if (demanda) " Abaixo da Figura 1, uma tabela fixa compara a amostra principal com a sensibilidade em que os meses não consolidados são mantidos, com o RR e o IC 95% nos dois níveis de referência, o período estimado e o número de dias e de óbitos de cada ajuste; o título da figura informa o período efetivamente estimado." else "", " O painel não dispõe de uma versão consolidada do SIM para comparar a completude dos meses recentes, o que é uma limitação do critério."),
    "### O modelo\n\n",
    pg("Cada recorte (local do óbito por faixa etária, ou local do óbito por raça/cor) e cada medida de calor têm um modelo próprio, adaptado do modelo de Morais et al. (script `02_model_fitting.R` do repositório citado acima): um modelo aditivo generalizado (GAM) com defasagens distribuídas (DLNM), ajustado com `mgcv::gam` por máxima verossimilhança restrita (REML). Os óbitos de cada dia seguem uma distribuição binomial negativa:"),
    "```\nlog(mu_t) = a + cb(calor, defasagem 0 a 10) + s(tempo) + s(dia do ano) + s(COVID)\n```\n\n",
    "- `cb` é a base cruzada (cross-basis) do pacote `dlnm`: uma função da exposição ao calor combinada com uma função da defasagem (spline natural com 3 graus de liberdade, gl), de 0 a ", M$lag, " dias.\n",
    "- `s(tempo)` é um spline de placa fina com base de dimensão k = ", M$k_tempo, ", que acompanha a tendência de longo prazo. O modelo de referência usa k = 12 para 12,5 anos; aqui, k cresce na mesma proporção para a série mais longa.\n",
    "- `s(dia do ano)` é um spline cíclico com base de dimensão k = 6 (sazonalidade anual).\n",
    "- `s(COVID)` é um spline cíclico com base de dimensão k = 8 sobre o número de dias desde o início do período da COVID-19 (", fd(M$covid[1]), " a ", fd(M$covid[2]), "), com valor zero fora dele.", if (demanda) " Se a caixa do período da COVID-19 estiver marcada, esse termo é retirado do modelo.", "\n",
    "- O modelo não inclui termo de dia da semana, como no modelo de referência.\n\n",
    pg(trocas),
    pg("O seletor oferece duas medidas de calor:"),
    "| Medida | Variável | Resposta à exposição | Níveis de referência do RR |\n|:--|:--|:--|:--|\n",
    "| Horas | horas do dia com índice de calor ≥ 36 °C | spline natural, 1 gl | ", h[1], " e ", h[2], " h por dia |\n",
    "| HAAT | graus-hora acima de 36 °C no dia (`auc36`) | spline penalizado, 15 gl | ", a[1], " e ", a[2], " °C·h por dia |\n\n",
    pg(rr_frase),
    retirar_p,
    curvas_p,
    mapa_p,
    cid_p,
    dia_p,
    "### Esperado sem calor\n\n",
    pg("O esperado de cada dia é o preditor linear do modelo com a cross-basis substituída pela cross-basis de exposição zero em todas as defasagens, isto é, o número de óbitos que o modelo prevê na ausência de calor (contrafactual). O esperado semanal é a soma dos sete esperados diários da semana (semanas epidemiológicas completas, de domingo a sábado). A faixa aproximada de variação de 95% é o esperado semanal ± 1,96 desvios-padrão, com aproximação normal e variância igual à soma das variâncias diárias (μ + μ²/θ) multiplicada por uma dispersão semanal φ (no mínimo 1). Dias vizinhos têm resíduos correlacionados, por epidemias e outros eventos que o modelo não descreve, e a soma de variâncias independentes subestima a variância da semana. O fator φ é a razão entre o erro quadrático semanal e essa soma, medida nos resíduos do modelo ajustado e fora do período da COVID-19. ",
        phi_frase, " Semanas com algum dia fora do ajuste ficam sem esperado."),
    pg("Três intervalos diferentes se confundem com facilidade. O intervalo de confiança do esperado mede a incerteza dos coeficientes sobre o número médio de óbitos sem calor. O intervalo preditivo mede onde pode cair o número de óbitos de uma semana, e reúne a variação aleatória dos óbitos e a incerteza dos coeficientes. A faixa do painel aproxima o intervalo preditivo com a variação aleatória e o φ, e deixa de fora a incerteza dos coeficientes. Por isso o painel usa o nome faixa aproximada de variação de 95%, e reserva IC 95% para o RR. A faixa não tem cobertura nominal garantida."),
    if (demanda) pg("O Quadro 5 da Figura 1 mostra, por período e por grupo de semanas (semanas de calor e demais), a proporção de semanas com o observado dentro, acima e abaixo da faixa. Os períodos são 2006 a 2010, 2011 a 2014, 2015 a 2019, 2020 a 2022 e 2023 em diante (ano epidemiológico da semana). Na primeira parte do quadro, a contagem usa a faixa da Figura 1, cujo modelo e cujo φ foram estimados com a série completa. Na segunda parte, pedida pelo usuário, o servidor retira cada período do ajuste, refaz o modelo com os demais anos, prevê o esperado sem calor das semanas retiradas e estima o φ só nas semanas que ficaram no ajuste. Os períodos do meio são previstos pela tendência dos vizinhos (interpolação), e o primeiro e o último, por extrapolação da tendência; o quadro marca esses dois com †. A especificação do modelo (graus de liberdade e defasagem) foi escolhida com a série completa, e por isso o quadro não é uma validação independente. Nas semanas de calor, os óbitos acima do limite superior misturam falta de calibração e efeito do calor; a calibração se lê nas demais semanas. A incerteza dos coeficientes do esperado semanal é estimada pelo método delta, com a matriz de covariância dos coeficientes condicional aos parâmetros de suavização, e o quadro informa quanto ela alargaria a faixa no ajuste principal."),
    pg("Como cada recorte tem modelo próprio, o esperado e a razão observado ÷ esperado variam conforme os filtros selecionados."),
    "### Comparação entre semanas de calor e as demais\n\n",
    pg("Semana de calor é aquela com pelo menos 3 dias de índice de calor máximo ≥ 36 °C (ou com pelo menos um dia em NC2 a NC5, os níveis de calor 2 a 5 do protocolo de calor da Prefeitura do Rio de Janeiro, Decreto Rio nº 54.740/2024, conforme o critério selecionado). A razão é a soma dos óbitos observados dividida pela soma dos esperados sem calor nas semanas do grupo, excluídas as semanas do período da COVID-19, as sem registro no SIM e as sem dados de clima. Na escala diária, dia exposto é o dia de calor (pelo menos 4 h com índice de calor ≥ 36 °C) e os três dias seguintes. Como o modelo usa defasagens de até 10 dias, parte do efeito ocorre também em dias fora desse intervalo de quatro dias."),
    "### O que mudou em relação ao painel anterior\n\n",
    pg("Na Figura 1 semanal do painel em Python, o esperado era obtido por um modelo apenas de tendência e sazonalidade, sem a variável de calor, ajustado a todas as semanas. Como esse modelo se ajusta à média dos dados, inclusive nas semanas de calor, a razão observado ÷ esperado ficava próxima de 1,00 em qualquer recorte. Nesta versão, o esperado é o contrafactual de um modelo que estima o efeito do calor em cada recorte, e a razão nas semanas de calor reflete esse efeito."),
    "### Limitações\n\n",
    "- É um estudo ecológico de séries temporais, descritivo e exploratório.\n",
    "- Cada recorte tem um modelo próprio, sem correção para comparações múltiplas. Recortes com poucos óbitos (mínimo de ", M$min_obitos, " no ajuste) produzem RR instáveis, com intervalos de confiança largos.\n",
    "- A faixa aproximada de variação de 95% não inclui a incerteza dos coeficientes, usa aproximação normal e um único φ para toda a série. A cobertura varia entre períodos", if (demanda) " (Quadro 5)" else "", " e não é garantida em 95%.\n",
    if (demanda) "- Quando o Quadro 1 da aba Diagnósticos e sensibilidades mostra autocorrelação dos resíduos (é o caso do ajuste principal para todos os locais e idades), os IC 95% dos RR, calculados como se os resíduos fossem independentes, podem ser estreitos demais. A dispersão φ semanal corrige só a faixa da Figura 1, e nenhuma das análises de sensibilidade remove essa dependência.\n",
    "- O período da COVID-19 é absorvido por um termo suave; por isso, o esperado nesse período não serve de comparação, e as semanas e os dias desse período ficam fora dos indicadores.", if (demanda) " Se a caixa de retirada estiver marcada, o período fica sem esperado.", "\n",
    if (demanda) "- Os modelos analisam contagens de óbitos, sem taxas por população: a população não entra como offset, e o spline de tempo absorve a variação lenta dela ao longo dos anos. A comparação de níveis entre populações ou entre anos exigiria taxas; o RR independe dessa limitação.\n",
    "- Não há dados de clima antes de 17/04/2007, e há falhas posteriores. Esses dias e os ", M$lag, " seguintes ficam fora do ajuste principal. A exclusão não corrige dias com poucas horas de medição, nos quais a contagem de horas de calor pode estar subestimada.\n",
    "- A classificação de mês não consolidado depende da própria série de óbitos e de uma referência de 12 meses; não foi comparada com uma versão consolidada do SIM.\n",
    "- As demais abas do painel em Python (RR por faixa e defasagem, horas por limiar, CIDs, unidades e clima) ainda utilizam o modelo anterior e serão migradas gradualmente.\n\n",
    "### Reprodução\n\n",
    repro, versao, "\n\n",
    "A paleta de cores foi adaptada do site EpiRio (Centro de Inteligência Epidemiológica, Prefeitura do Rio). Os gráficos são gerados com a biblioteca Chart.js 4.4.1, incorporada ", if (demanda) "a este painel" else "a este arquivo", ".\n")
}
